import { useVersionsPublishNotice } from "@/wab/client/components/sidebar-tabs/versions-tab/useVersionsPublishNotice";
import type { MessageKey } from "@/wab/client/i18n/locales";
// This is a skeleton starter React component generated by Plasmic.
// Feel free to edit as you see fit.
import { DevContainer } from "@/wab/client/components/dev";
import { NavigationDropdown } from "@/wab/client/components/sidebar-tabs/ProjectPanel/NavigationDropdown";
import { PanelCloseButton } from "@/wab/client/components/studio/PanelCloseButton";
import { useI18n } from "@/wab/client/i18n";
import { Tabs } from "antd";

import { OutlineTab } from "@/wab/client/components/sidebar-tabs/outline-tab";
import { ResponsivenessPanel } from "@/wab/client/components/sidebar-tabs/ResponsivenessPanel";
import { VersionsTab } from "@/wab/client/components/sidebar-tabs/versions-tab";
import { FindReferencesModal } from "@/wab/client/components/sidebar/FindReferencesModal";
import { ImageAssetsPanel } from "@/wab/client/components/sidebar/image-asset-controls";
import LeftComponentsPanel from "@/wab/client/components/sidebar/LeftComponentsPanel";
import LeftExprsSearchPanel from "@/wab/client/components/sidebar/LeftExprsSearchPanel";
import LeftGeneralDataTokensPanel from "@/wab/client/components/sidebar/LeftGeneralDataTokensPanel";
import LeftGeneralTokensPanel from "@/wab/client/components/sidebar/LeftGeneralTokensPanel";
import LeftLintIssuesPanel from "@/wab/client/components/sidebar/LeftLintIssuesPanel";
import LeftProjectSettingsPanel from "@/wab/client/components/sidebar/LeftProjectSettingsPanel";
import LeftSplitsPanel from "@/wab/client/components/sidebar/LeftSplitsPanel";

import { AnimationSequencesPanel } from "@/wab/client/components/sidebar/AnimationSequenceControls";
import { LibrariesPanel } from "@/wab/client/components/sidebar/LibrariesPanel";
import { MixinsPanel } from "@/wab/client/components/sidebar/MixinControls";
import { SidebarModalProvider } from "@/wab/client/components/sidebar/SidebarModal";
import { DefaultStylesPanel } from "@/wab/client/components/sidebar/ThemesControls";
import { UserManagedFontsPanel } from "@/wab/client/components/sidebar/UserManagedFonts";
import { providesSidebarPopupSetting } from "@/wab/client/components/style-controls/StyleComponent";
import { editorLeftRailLayout } from "@/wab/client/components/ui/layout-styles";
import { Icon } from "@/wab/client/components/widgets/Icon";
import { ListStack } from "@/wab/client/components/widgets/ListStack";
import { useResizableHandle } from "@/wab/client/hooks/useResizableHandle";
import { DataTokenIcon } from "@/wab/client/icons";
import ComponentIcon from "@/wab/client/plasmic/plasmic_kit/PlasmicIcon__Component";
import TokenIcon from "@/wab/client/plasmic/plasmic_kit/PlasmicIcon__Token";
import PlasmicLeftPane from "@/wab/client/plasmic/plasmic_kit_left_pane/PlasmicLeftPane";
import { StudioCtx } from "@/wab/client/studio-ctx/StudioCtx";
import { HighlightBlinker } from "@/wab/commons/components/HighlightBlinker";
import { useSignalListener } from "@/wab/commons/components/use-signal-listener";
import { XDraggable } from "@/wab/commons/components/XDraggable";
import { extractDataTokenUsages } from "@/wab/commons/DataToken";
import { cx, spawn, switchType } from "@/wab/shared/common";
import { getComponentDisplayName } from "@/wab/shared/core/components";
import { extractComponentUsages } from "@/wab/shared/core/sites";
import { extractTokenUsages } from "@/wab/shared/core/styles";
import { Component, DataToken, StyleToken } from "@/wab/shared/model/classes";
import { LeftTabKey } from "@/wab/shared/ui-config-utils";
import { observer } from "mobx-react";
import React, { useState } from "react";

interface LeftPaneProps {
  studioCtx: StudioCtx;
  className?: string;
}

const LeftPane = observer(function LeftPane(props: LeftPaneProps) {
  const { t } = useI18n();
  const { studioCtx } = props;
  const navigationTab = studioCtx.navigationPanel;
  const setNavigationTab = studioCtx.setNavigationPanel;
  useSignalListener(
    studioCtx.showNavigationPanelRequested,
    (tab) => {
      const closePanel =
        tab !== "pages" &&
        tab === studioCtx.navigationPanel &&
        studioCtx.leftTabKey === "outline" &&
        !studioCtx.showAddDrawer() &&
        !studioCtx.panelsHidden;
      setNavigationTab(tab);
      if (tab === "pages" && studioCtx.projectSearchInputRef.current) {
        studioCtx.focusOnProjectSearchInput();
      }
      spawn(
        studioCtx.changeUnsafe(() => {
          if (studioCtx.panelsHidden) {
            studioCtx.togglePanels();
          }
          studioCtx.setShowAddDrawer(false);
          studioCtx.switchLeftTab(closePanel ? undefined : "outline");
        }),
      );
    },
    [studioCtx],
  );
  React.useEffect(() => {
    if (navigationTab === "pages" && studioCtx.leftTabKey === "outline") {
      studioCtx.focusOnProjectSearchInput();
    }
  }, [navigationTab, studioCtx.leftTabKey]);
  // const [hover, setHover] = React.useState(false);

  const wrapTab = (
    tabKey: LeftTabKey,
    panel: React.ReactNode,
    unmount = false,
  ) => {
    return (
      (!unmount || studioCtx.leftTabKey === tabKey) && (
        <div
          className="flex-col flex-fill overflow-hidden"
          style={tabKey === studioCtx.leftTabKey ? {} : { display: "none" }}
        >
          {panel}
        </div>
      )
    );
  };

  const panelTitles: Partial<Record<LeftTabKey, MessageKey>> = {
    tokens: "Style tokens",
    dataTokens: "Data tokens",
    mixins: "Style presets",
    animationSequences: "Animations",
    components: "Components",
    expressions: "Expressions",
    themes: "Default styles theme",
    images: "Images and icons",
    fonts: "Custom fonts",
    responsiveness: "Responsive breakpoints",
    versions: "Published versions",
    settings: "Project settings",
    splits: "Split content",
  };
  const leftPaneRef = React.useRef<HTMLDivElement>(null);

  const { onDragStart, onDrag, onDragStop } = useResizableHandle({
    panelRef: leftPaneRef,
    onChange: React.useCallback(
      (newWidth: number) => {
        spawn(
          studioCtx.changeUnsafe(() => {
            studioCtx.leftPaneWidth = newWidth;
          }),
        );
      },
      [studioCtx],
    ),
  });

  const { useVersionsCTA, dismissVersionsCTA } =
    useVersionsPublishNotice(studioCtx);

  const isLoggedIn = studioCtx.appCtx.selfInfo != null;

  const [highlightPane, setHighlightPane] = useState(false);

  useSignalListener(studioCtx.leftPanelHighlightingRequested, () => {
    setHighlightPane(true);
    setTimeout(() => setHighlightPane(false), 2000);
  });

  return providesSidebarPopupSetting({ left: true })(
    <SidebarModalProvider containerSelector={".canvas-editor__left-pane"}>
      <DevContainer
        className={cx({
          flex: true,
          // monochrome: !hover,
          "canvas-editor__left-pane-container": true,
        })}
        style={{
          position: "absolute",
          left: editorLeftRailLayout.left,
          top: 82,
          height: "calc(100dvh - 170px)",
        }}
        showControls={studioCtx.showDevControls}
        // onMouseEnter={() => setHover(true)}
        // onMouseLeave={() => setHover(false)}
      >
        <PlasmicLeftPane
          leftTabStrip={{ props: { useVersionsCTA } }}
          type={
            studioCtx.leftTabKey === "libraries"
              ? undefined
              : studioCtx.leftTabKey
          }
          paneContainer={{
            props: {
              className: "canvas-editor__left-pane auto-pointer-events",
              style: {
                position: "absolute",
                left: `calc(100% + ${editorLeftRailLayout.panelGap}px)`,
                top: 0,
                width: studioCtx.leftPaneWidth,
                display:
                  studioCtx.leftTabKey &&
                  !studioCtx.showAddDrawer() &&
                  !(
                    studioCtx.leftTabKey === "libraries" &&
                    studioCtx.isDraggingObject()
                  )
                    ? undefined
                    : "none",
              },
            },

            wrapChildren: (children) => (
              <>
                {studioCtx.leftTabKey &&
                  studioCtx.leftTabKey !== "libraries" && (
                    <div className="editor-panel-header">
                      {studioCtx.leftTabKey === "outline" ? (
                        <Tabs
                          className="editor-navigation-tabs"
                          activeKey={navigationTab}
                          onChange={(key) =>
                            setNavigationTab(
                              key === "pages" ? "pages" : "outline",
                            )
                          }
                          items={[
                            {
                              key: "pages",
                              label: (
                                <span id="proj-nav-button">
                                  {t("Documents")}
                                </span>
                              ),
                            },
                            { key: "outline", label: t("Layers") },
                          ]}
                        />
                      ) : (
                        <>
                          <strong className="editor-panel-title">
                            {t(
                              studioCtx.leftTabKey === "lint"
                                ? "Issues"
                                : (panelTitles[studioCtx.leftTabKey] ??
                                    "Assets"),
                            )}
                          </strong>
                        </>
                      )}
                      <PanelCloseButton
                        onClick={() =>
                          spawn(
                            studioCtx.changeUnsafe(() =>
                              studioCtx.switchLeftTab(undefined),
                            ),
                          )
                        }
                      />
                    </div>
                  )}
                <ListStack style={{ flex: 1, minHeight: 0 }}>
                  {children}
                </ListStack>
                <XDraggable
                  onStart={onDragStart}
                  onStop={onDragStop}
                  onDrag={onDrag}
                  minPx={0}
                >
                  <div className="left-pane-resizer auto-pointer-events" />
                </XDraggable>
              </>
            ),
          }}
          paneContent={{
            props: {
              ref: leftPaneRef,
              children: (
                <>
                  {wrapTab("responsiveness", <ResponsivenessPanel />)}
                  {wrapTab(
                    "outline",
                    navigationTab === "pages" ? (
                      <div className="editor-page-navigation">
                        <NavigationDropdown
                          onClose={() => setNavigationTab("outline")}
                        />
                      </div>
                    ) : (
                      <OutlineTab />
                    ),
                  )}
                  {wrapTab("tokens", <LeftGeneralTokensPanel />)}
                  {wrapTab("dataTokens", <LeftGeneralDataTokensPanel />)}
                  {wrapTab("mixins", <MixinsPanel />)}
                  {wrapTab("animationSequences", <AnimationSequencesPanel />)}
                  {wrapTab("components", <LeftComponentsPanel />)}
                  {wrapTab("expressions", <LeftExprsSearchPanel />)}
                  {wrapTab("themes", <DefaultStylesPanel />)}
                  {wrapTab("images", <ImageAssetsPanel />)}
                  {wrapTab("fonts", <UserManagedFontsPanel />)}
                  {wrapTab("libraries", <LibrariesPanel />, true)}
                  {isLoggedIn &&
                    wrapTab(
                      "versions",
                      <VersionsTab
                        useVersionsCTA={useVersionsCTA}
                        dismissVersionsCTA={dismissVersionsCTA}
                      />,
                      true,
                    )}
                  {wrapTab("settings", <LeftProjectSettingsPanel />)}
                  {wrapTab("splits", <LeftSplitsPanel />)}
                  {wrapTab("lint", <LeftLintIssuesPanel />, true)}
                  {highlightPane && <HighlightBlinker />}
                </>
              ),
            },
          }}
        />
      </DevContainer>
      {(studioCtx.findReferencesComponent ||
        studioCtx.findReferencesStyleToken ||
        studioCtx.findReferencesDataToken) && (
        <FindReferencesModal
          studioCtx={studioCtx}
          {...getFindReferencesProps(
            studioCtx,
            [
              studioCtx.findReferencesComponent,
              studioCtx.findReferencesStyleToken,
              studioCtx.findReferencesDataToken,
            ].find((x) => x != null) as Component | StyleToken | DataToken,
          )}
        />
      )}
    </SidebarModalProvider>,
  );
});

const getFindReferencesProps = (
  studioCtx: StudioCtx,
  reference: Component | StyleToken | DataToken,
) => {
  return switchType(reference)
    .when(Component, (component) => ({
      displayName: getComponentDisplayName(component),
      icon: (
        <Icon
          icon={ComponentIcon}
          className="component-fg custom-svg-icon--lg monochrome-exempt"
        />
      ),
      usageSummary: extractComponentUsages(studioCtx.site, component),
      onClose: () => {
        studioCtx.findReferencesComponent = undefined;
      },
    }))
    .when(StyleToken, (token) => ({
      displayName: token.name,
      icon: (
        <Icon
          icon={TokenIcon}
          className="token-fg custom-svg-icon--lg monochrome-exempt"
        />
      ),
      usageSummary: extractTokenUsages(studioCtx.site, token)[1],
      onClose: () => {
        studioCtx.findReferencesStyleToken = undefined;
      },
    }))
    .when(DataToken, (token) => ({
      displayName: token.name,
      icon: (
        <Icon
          icon={DataTokenIcon}
          className="data-token-fg custom-svg-icon--lg monochrome-exempt"
        />
      ),
      usageSummary: extractDataTokenUsages(
        studioCtx.siteInfo.id,
        studioCtx.site,
        token,
      ),
      onClose: () => {
        studioCtx.findReferencesDataToken = undefined;
      },
    }))
    .result();
};

export default LeftPane as React.FunctionComponent<LeftPaneProps>;
